const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const dayContent={life:`<article class="day-entry"><h3>很普通，也很珍贵的一天</h3><p>午后的光落在毯子上。酱酱抬头看了我一会儿，又安心地窝了回去。</p><div class="day-entry-photos"><img src="assets/jiangjiang-photo.jpg" alt="酱酱抬头看向镜头"><img src="assets/jiangjiang-sleep.jpg" alt="酱酱安心地窝在被子里"></div><small>照片说明 / 抬头看我的那一刻</small><div class="tagline"><span>普通的一天</span><span>午后</span><span>原文保留</span></div></article>`,health:`<article class="day-entry"><h3>每一项，都写具体。</h3><table class="health-table"><tbody><tr><td>饮食</td><td>按平时食量吃完</td></tr><tr><td>体重</td><td>4.2 kg · 保留单位</td></tr><tr><td>饮水</td><td>未填写 / 未知</td></tr><tr><td>用药</td><td>未填写 / 未知</td></tr></tbody></table><p class="demo-notice">以上是功能演示数据，不代表酱酱的真实健康状态。类别标签不等于观察结果。</p><div class="tagline"><span>关联后续</span><span>整理给医生看</span></div></article>`};
function selectTab(selector,target){$$(selector).forEach(b=>b.setAttribute('aria-selected',String(b===target)));}
function setDay(mode){$('#day-content').innerHTML=dayContent[mode];const f='assets/app-'+(mode==='life'?'life':'health-fields')+'.png';$('#day-screen').src=f;$('#day-screen').alt=mode==='life'?'当前 App 的日常记录实际界面':'当前 App 的健康具体观察实际界面';$('#day-screen').closest('button').dataset.image=f;$('#day-screen').closest('button').dataset.caption='真实 H5 · '+(mode==='life'?'日常与照片':'健康与观察')+'；内容为独立演示数据';}
$$('[data-day]').forEach(b=>b.onclick=()=>{selectTab('[data-day]',b);setDay(b.dataset.day)});setDay('life');
$$('[data-care]').forEach((b,i)=>b.onclick=()=>{selectTab('[data-care]',b);const f='assets/app-'+b.dataset.care+'.png';$('#care-screen').src=f;$('#care-screen').alt=b.textContent+'实际界面';$('#care-screen').closest('button').dataset.image=f;$('#care-screen').closest('button').dataset.caption='真实 H5 · '+b.textContent+'；本次未调用模型或发送问题';$('#care-count').textContent='0'+(i+1)+' / 03';});
const albumContent={records:`<article class="album-entry"><img src="assets/jiangjiang-photo.jpg" alt="酱酱坐在毯子上"><div><small>2026.10.22 · 日常记录</small><h4>很普通，也很珍贵的一天</h4><p>午后的光落在毯子上。酱酱抬头看了我一会儿，又安心地窝了回去。</p><div class="tagline"><span>普通的一天</span><span>午后</span></div></div></article><article class="album-entry"><img src="assets/jiangjiang-close.jpg" alt="酱酱靠在主人身边"><div><small>某个安静的下午 · 内容示例</small><h4>靠近一点，再近一点。</h4><p>照片的说明，也能成为以后找回这一刻的线索。</p></div></article>`,photos:`<div class="photo-grid"><figure><img src="assets/jiangjiang-sleep.jpg" alt="酱酱熟睡"><figcaption>安心睡一觉</figcaption></figure><figure><img src="assets/jiangjiang-close.jpg" alt="酱酱靠近主人"><figcaption>熟悉的依靠</figcaption></figure><figure><img src="assets/jiangjiang-stretch.jpg" alt="酱酱伸展身体"><figcaption>长长的午后</figcaption></figure></div>`,works:`<div class="album-work"><img src="assets/work-postcard.png" alt="实际导出的酱酱明信片"><div><span class="eyebrow">SAVED WORK</span><h3>照片明信片</h3><p>来自这一日的生活文字、照片与说明。作品按保存时的内容独立留存。</p><a class="line-link" href="assets/work-postcard.png" download="酱酱-明信片.png">下载实际 PNG ↓</a></div></div>`};
$$('[data-album]').forEach(b=>b.onclick=()=>{selectTab('[data-album]',b);$('#album-content').innerHTML=albumContent[b.dataset.album]});$('#album-content').innerHTML=albumContent.records;
const steps=[['先选这一页要讲什么。','原文、手写观察、照片、说明、标题、名字和小标签逐项选择。健康项目需要主动勾选，私人内容不会默认进入作品。','来源仍在；作品只收下选中的内容。'],['一种内容，找到合适的版式。','照片明信片留给画面，今日记录卡承接细节，一句话和写给你的信承接不同长度。内容不兼容时，会确认是否另做一版。','可以恢复前一个版本，不用从头重来。'],['给文字和照片留一点呼吸。','纸纹、横线、窗影、植物线描与相纸边可组合选择。名字和日期可隐藏，照片可以完整展示或调整裁切。','细节在纸面上，选择权在你手里。'],['最后，盖上属于它的印记。','朱印或压印、左下或右下，也可以自由拖动、旋转和缩放。支持撤回、重置与找回；遮挡和靠边时提供提示。','旧作品保留原样，新作品再主动选用。']];
function step(i){$('#studio-content').innerHTML=`<h3>${steps[i][0]}</h3><p>${steps[i][1]}</p><small>${steps[i][2]}</small>`}
$$('[data-step]').forEach(b=>b.onclick=()=>{selectTab('[data-step]',b);step(+b.dataset.step)});step(0);
function renderFeatures(){const q=$('#feature-search').value.trim().toLowerCase(),s=$('#feature-status').value;let count=0;$('#feature-directory').innerHTML=featureGroups.map((g,i)=>{const entries=g.items.filter(([title,desc,status])=>(!q||(g.title+title+desc).toLowerCase().includes(q))&&(s==='all'||(status||'local')===s));count+=entries.length;if(!entries.length)return '';return `<details class="feature-group" ${q||s!=='all'||i===0?'open':''}><summary><span>0${i+1}</span><h3>${g.title}</h3><small>${entries.length} 个细节</small></summary><div class="feature-rows">${entries.map(([title,desc,status])=>`<article class="feature-row"><div><h4>${title}</h4>${status?`<span class="status">${status==='service'?'需要服务连接':'预览 / 未接入'}</span>`:''}</div><p>${desc}</p></article>`).join('')}<p class="feature-source">实现来源 / ${g.source}</p></div></details>`}).join('')||'<p class="empty-results">没有找到这个词。可以试试“照片”“草稿”或“日期”。</p>';$('#feature-count').textContent=count+' 项细节';}
$('#feature-search').addEventListener('input',renderFeatures);$('#feature-status').addEventListener('change',renderFeatures);renderFeatures();
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$('#feature-search').value=b.dataset.filter;$('#feature-status').value='all';renderFeatures()}));
document.addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(b){$('#large-image').src=b.dataset.image;$('#large-image').alt=b.dataset.caption;$('#image-caption').textContent=b.dataset.caption;$('#image-dialog').showModal();}if(e.target.closest('[data-watch]')){$('#film-dialog').showModal();$('#film-dialog video').load();}if(e.target.closest('.dialog-close'))e.target.closest('dialog').close();});
$$('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{if(d.id==='film-dialog')d.querySelector('video').pause();});});
// Keyboard arrows traverse tab groups; focus remains on the selected control.
$$('[role=tablist]').forEach(list=>list.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...list.querySelectorAll('[role=tab]')],i=tabs.indexOf(document.activeElement);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click()}));
const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
if(!reduced&&'IntersectionObserver'in window){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');io.unobserve(e.target)}}),{threshold:.08});$$('.section-heading,.identity-words,.care-copy,.studio-heading,.memory-layout>div,.system-grid article').forEach(el=>{el.classList.add('reveal');io.observe(el)});}
let pending=false;function progress(){const max=document.documentElement.scrollHeight-innerHeight;$('.reading-progress').style.transform=`scaleX(${max?scrollY/max:0})`;pending=false;}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(progress)}},{passive:true});progress();
if('IntersectionObserver'in window){const sections=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){$$('.book-navigation a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id));}})},{rootMargin:'-15% 0px -65%'});$$('.chapter').forEach(s=>sections.observe(s));}
